(function(){'use strict';function wrapHeroContent(){var blocks=document.querySelectorAll('.featured-block.fc-feat-style-hero');blocks.forEach(function(block){var wrappers=block.querySelectorAll('.fc-item-block-featured-wrapper-innerbox');wrappers.forEach(function(box){if(box.querySelector('.fc-content-col'))return;var figure=box.querySelector('figure.image_featured');var wrap=document.createElement('div');wrap.className='fc-content-col';var children=Array.prototype.slice.call(box.children);children.forEach(function(child){if(child !==figure && child.tagName !=='HEADER')wrap.appendChild(child);});if(wrap.children.length > 0)box.appendChild(wrap);});});}function applyGridFallback(){if(window.CSS && CSS.supports && CSS.supports('selector(:has(*))'))return;var vw=window.innerWidth;var isMobile=vw <=640;var isTablet=vw <=768;document.querySelectorAll('.featured-block.fc-items-block').forEach(function(block){var wrapper=block.querySelector('[data-total]');if(!wrapper)return;var total=parseInt(wrapper.dataset.total,10);if(!total || total < 2)return;var isOverlay=block.classList.contains('fc-feat-style-overlay');var isMinimal=block.classList.contains('fc-feat-style-minimal');var first=block.querySelector('[data-index="0"]');if(first){first.style.gridColumn='';first.style.gridRow='';}if(isMobile){block.style.display='grid';block.style.gridTemplateColumns='1fr';block.querySelectorAll('[data-index]').forEach(function(w){w.style.gridColumn='';w.style.gridRow='';});return;}block.style.display='grid';if(total===2){block.style.gridTemplateColumns='1fr 1fr';}else if(total===3){if(isOverlay){block.style.gridTemplateColumns=isTablet ? '1fr 1fr':'repeat(3,1fr)';if(first){first.style.gridColumn='unset';first.style.gridRow='unset';}}else if(isMinimal){block.style.gridTemplateColumns=isTablet ? '1fr 1fr':'repeat(3,1fr)';}else{block.style.gridTemplateColumns='1fr 1fr';if(first)first.style.gridColumn='1/-1';}}else if(total===4 || total===5){if(isOverlay){block.style.gridTemplateColumns=isTablet ? '1fr 1fr':'repeat(4,1fr)';if(first){first.style.gridColumn='unset';first.style.gridRow='unset';}}else if(isMinimal){block.style.gridTemplateColumns=isTablet ? '1fr 1fr':'repeat(4,1fr)';}else{block.style.gridTemplateColumns=isTablet ? '1fr 1fr':'repeat(3,1fr)';if(first)first.style.gridColumn='1/-1';}}block.querySelectorAll('article.fc-item-featured,article.fc-item-standard').forEach(function(art){if(art.querySelector('figure')){var hdr=art.querySelector('header.tool');if(hdr)hdr.style.borderRadius='var(--r,8px)var(--r,8px)0 0';}});block.querySelectorAll('.fc-item-block-featured-wrapper-innerbox').forEach(function(box){if(!box.querySelector('figure'))box.classList.add('fc-no-image');else box.classList.remove('fc-no-image');});});document.querySelectorAll('#fc-yootheme-grid .fc-featured-section').forEach(function(section){var wrapper=section.querySelector('[data-total]');if(!wrapper)return;var total=parseInt(wrapper.dataset.total,10);if(!total || total < 2)return;var first=section.querySelector('[data-index="0"]');if(first){first.style.gridColumn='';first.style.gridRow='';}if(isMobile){section.style.gridTemplateColumns='1fr';section.querySelectorAll('[data-index]').forEach(function(w){w.style.gridColumn='';w.style.gridRow='';});return;}if(total===2){section.style.gridTemplateColumns='1fr 1fr';}else if(total===3){section.style.gridTemplateColumns='1fr 1fr';if(isTablet){if(first){first.style.gridRow='auto';first.style.gridColumn='1/-1';}section.querySelectorAll('[data-index="1"],[data-index="2"]').forEach(function(w){w.style.gridColumn='unset';});}else{if(first){first.style.gridRow='1/3';first.style.gridColumn='1';}section.querySelectorAll('[data-index="1"],[data-index="2"]').forEach(function(w){w.style.gridColumn='2';});}}else if(total===4){section.style.gridTemplateColumns=isTablet ? '1fr 1fr':'repeat(3,1fr)';if(first){first.style.gridColumn='1/-1';if(isTablet)first.style.gridRow='auto';}}});}function initAnimations(){if(!window.IntersectionObserver)return;function setupBlock(block,animAttr){var anim=block.getAttribute(animAttr);if(!anim)return;var items=block.querySelectorAll(animAttr==='data-feat-anim' ? '.fc-item-block-featured-wrapper':'.fc-item-block-standard-wrapper');items.forEach(function(item,i){item.classList.add('fc-anim-ready','fc-anim-'+anim);item.style.transitionDelay=Math.min(i * 80,400)+ 'ms';});var obs=new IntersectionObserver(function(entries){entries.forEach(function(entry){if(entry.isIntersecting){entry.target.classList.add('fc-anim-visible');obs.unobserve(entry.target);}});},{threshold:0.08,rootMargin:'0px 0px -40px 0px'});items.forEach(function(item){obs.observe(item);});}document.querySelectorAll('.featured-block.fc-items-block[data-feat-anim]').forEach(function(b){setupBlock(b,'data-feat-anim');});document.querySelectorAll('.standard-block.fc-items-block[data-std-anim]').forEach(function(b){setupBlock(b,'data-std-anim');});}var _resizeTimer;function onResize(){clearTimeout(_resizeTimer);_resizeTimer=setTimeout(applyGridFallback,120);}function init(){wrapHeroContent();applyGridFallback();initAnimations();window.addEventListener('resize',onResize);}if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',init);}else{init();}})();